mapper.select:
SELECT prl.id, prl.ledger_code, prl.payment_deadline_time, prl.ent_id, ei.ent_name,
prl.illegal_type_id, itd.type_name AS illegal_type_name,
prl.illegal_level_id, ild.level_name AS illegal_level_name,
prl.ent_rectify_record_id, err.rectify_status,
prl.punish_notice_id, pn.notice_code,
prl.draft_punish_amt, prl.legal_basis, prl.evidence_url,
prl.review_status, prl.review_by, su.user_name as review_by_name, prl.review_time,
prl.cancel_reason_id, prl.cancel_time,
prl.draft_time,
prl.create_time, prl.update_time
FROM punish_review_ledger prl
LEFT JOIN enterprise_info ei ON prl.ent_id = ei.id
LEFT JOIN illegal_type_dict itd ON prl.illegal_type_id = itd.id
LEFT JOIN illegal_level_dict ild ON prl.illegal_level_id = ild.id
LEFT JOIN ent_rectify_record err ON prl.ent_rectify_record_id = err.id
LEFT JOIN punish_notice pn ON prl.punish_notice_id = pn.id LEFT JOIN sys_user su ON prl.review_by = su.id
prl.deleted = b'0'
AND prl.id IN
#{id}
AND prl.ledger_code LIKE CONCAT('%', #{ledgerCode}, '%')
AND prl.ent_id = #{entId}
AND ei.ent_name LIKE CONCAT('%', #{entName}, '%')
AND prl.illegal_type_id = #{illegalTypeId}
AND prl.illegal_level_id = #{illegalLevelId}
AND prl.review_status = #{reviewStatus}
AND prl.draft_time >= #{draftTimeStart}
AND prl.draft_time <= #{draftTimeEnd}
AND prl.review_time >= #{reviewTimeStart}
AND prl.review_time <= #{reviewTimeEnd}
AND prl.cancel_time >= #{cancelTimeStart}
AND prl.cancel_time <= #{cancelTimeEnd}
ORDER BY prl.id DESC, prl.create_time DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(1) FROM punish_review_ledger prl
LEFT JOIN enterprise_info ei ON prl.ent_id = ei.id
LEFT JOIN illegal_type_dict itd ON prl.illegal_type_id = itd.id
LEFT JOIN illegal_level_dict ild ON prl.illegal_level_id = ild.id
LEFT JOIN ent_rectify_record err ON prl.ent_rectify_record_id = err.id
LEFT JOIN punish_notice pn ON prl.punish_notice_id = pn.id
prl.deleted = b'0'
AND prl.id IN
#{id}
AND prl.ledger_code LIKE CONCAT('%', #{ledgerCode}, '%')
AND prl.ent_id = #{entId}
AND ei.ent_name LIKE CONCAT('%', #{entName}, '%')
AND prl.illegal_type_id = #{illegalTypeId}
AND prl.illegal_level_id = #{illegalLevelId}
AND prl.review_status = #{reviewStatus}
